import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { toJob, type JobRow } from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;
const WORKER_FRESH_MS = 3000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectWorkerBeat = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'");
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_after, idempotency_key, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?, ?)`,
);

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, headers);
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        req.removeAllListeners('data');
        req.resume();
        resolve(undefined);
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function headerValue(v: string | string[] | undefined): string | undefined {
  return Array.isArray(v) ? v.join(', ') : v;
}

function isInteger(v: unknown): v is number {
  return typeof v === 'number' && Number.isInteger(v);
}

/** Validates a parsed request body, appending any problems to `errors`. */
function validateBody(body: unknown, errors: FieldError[]): NewJob | undefined {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    errors.push({ field: 'body', message: 'body must be a JSON object' });
    return undefined;
  }
  const obj = body as Record<string, unknown>;
  let ok = true;
  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) {
      errors.push({ field: key, message: 'unknown field' });
      ok = false;
    }
  }

  const input = obj.input;
  if (input === undefined) {
    errors.push({ field: 'input', message: 'input is required' });
    ok = false;
  } else if (typeof input !== 'string') {
    errors.push({ field: 'input', message: 'input must be a string' });
    ok = false;
  } else if (input.length < 1 || input.length > 1000) {
    errors.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
    ok = false;
  } else if (input.trim().length === 0) {
    errors.push({ field: 'input', message: 'input must not be only whitespace' });
    ok = false;
  }

  const steps = obj.steps === undefined ? DEFAULT_STEPS : obj.steps;
  if (!isInteger(steps) || steps < 1 || steps > 20) {
    errors.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
    ok = false;
  }

  const failAttempts = obj.failAttempts === undefined ? DEFAULT_FAIL_ATTEMPTS : obj.failAttempts;
  if (!isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) {
    errors.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
    ok = false;
  }

  if (!ok || typeof input !== 'string' || !isInteger(steps) || !isInteger(failAttempts)) return undefined;
  return { input, steps, failAttempts };
}

/**
 * Creates a job, or replays/conflicts with the job previously created under `key`.
 * Runs in an IMMEDIATE transaction so the lookup and insert cannot interleave with another writer.
 */
function createJob(newJob: NewJob, key: string | undefined): { row: JobRow; created: boolean } | 'conflict' {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = selectByKey.get(key) as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        const same =
          existing.input === newJob.input && existing.steps === newJob.steps && existing.fail_attempts === newJob.failAttempts;
        return same ? { row: existing, created: false } : 'conflict';
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    insertJob.run(id, newJob.input, newJob.steps, newJob.failAttempts, key ?? null, now, now);
    const row = selectById.get(id) as unknown as JobRow;
    db.exec('COMMIT');
    return { row, created: true };
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const errors: FieldError[] = [];

  const key = headerValue(req.headers['idempotency-key']);
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const contentType = (headerValue(req.headers['content-type']) ?? '').split(';')[0]!.trim().toLowerCase();
  let newJob: NewJob | undefined;
  if (contentType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (raw === undefined) {
    errors.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      errors.push({ field: 'body', message: 'body is not valid JSON' });
      parsed = undefined;
    }
    if (errors.length === 0) newJob = validateBody(parsed, errors);
  }

  if (errors.length > 0 || newJob === undefined) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  const result = createJob(newJob, key);
  if (result === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, result.created ? 201 : 200, toJob(result.row));
}

function workerIsUp(): boolean {
  const beat = selectWorkerBeat.get() as { at: number } | undefined;
  return beat !== undefined && Date.now() - beat.at <= WORKER_FRESH_MS;
}

const ROUTES: Array<{ test: (path: string) => boolean; methods: string[] }> = [
  { test: (p) => p === '/', methods: ['GET'] },
  { test: (p) => p === '/health', methods: ['GET'] },
  { test: (p) => p === '/api/jobs', methods: ['GET', 'POST'] },
  { test: (p) => /^\/api\/jobs\/[^/]+$/.test(p), methods: ['GET'] },
];

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const route = ROUTES.find((r) => r.test(pathname));
  if (!route) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }
  if (!route.methods.includes(method)) {
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`, undefined, {
      allow: route.methods.join(', '),
    });
    return;
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    sendJson(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') return handleCreateJob(req, res);
    const rows = selectAll.all() as unknown as JobRow[];
    sendJson(res, 200, { jobs: rows.map(toJob) });
    return;
  }
  const id = decodeURIComponent(pathname.slice('/api/jobs/'.length));
  const row = selectById.get(id) as JobRow | undefined;
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  sendJson(res, 200, toJob(row));
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

