import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase } from './db.ts';
import type { JobRow } from './jobs.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1000;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const TRANSIENT_ERROR = 'transient failure';

const db: DatabaseSync = openDatabase();
let stopping = false;

const upsertBeat = db.prepare(
  "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
);
const deleteBeat = db.prepare("DELETE FROM heartbeats WHERE name = 'worker'");
const recoverRunning = db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
);
const selectNext = db.prepare(
  "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1",
);
const claim = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?",
);
const setProgress = db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?');
const requeueForRetry = db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE seq = ?",
);
const markFailed = db.prepare(
  "UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, progress_completed = 0, updated_at = ? WHERE seq = ?",
);
const markCompleted = db.prepare(
  "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE seq = ?",
);

function beat(): void {
  upsertBeat.run(Date.now());
}

/** Claims the oldest runnable queued job in one transaction, marking it running for a new attempt. */
function claimNext(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = selectNext.get(Date.now()) as JobRow | undefined;
    if (row) claim.run(new Date().toISOString(), row.seq);
    db.exec('COMMIT');
    return row ? { ...row, attempts: row.attempts + 1, progress_completed: 0, status: 'running' } : undefined;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

/**
 * Runs one attempt of a job. Returns early without writing a final state if the worker is stopping;
 * the job then stays `running` and is requeued by the next worker start.
 */
async function runAttempt(job: JobRow): Promise<void> {
  const now = () => new Date().toISOString();

  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (job.attempts < MAX_ATTEMPTS) {
      requeueForRetry.run(Date.now() + RETRY_DELAY_MS, now(), job.seq);
    } else {
      markFailed.run(TRANSIENT_ERROR, now(), job.seq);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress.run(step, now(), job.seq);
  }
  markCompleted.run(job.input.toUpperCase(), now(), job.seq);
}

async function main(): Promise<void> {
  for (const signal of ['SIGINT', 'SIGTERM'] as const) {
    process.on(signal, () => {
      stopping = true;
    });
  }

  beat();
  const heartbeat = setInterval(beat, HEARTBEAT_MS);
  // A job left `running` by a dead worker is processed again.
  recoverRunning.run(new Date().toISOString());

  console.log('worker started');
  while (!stopping) {
    const job = claimNext();
    if (!job) {
      await sleep(POLL_MS);
      continue;
    }
    await runAttempt(job);
  }

  clearInterval(heartbeat);
  deleteBeat.run();
  db.close();
  console.log('worker stopped');
}

main().catch((err: unknown) => {
  console.error('worker failed:', err);
  process.exit(1);
});

