2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Job tracker</title>
7	  <style>
8	    body { font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 48rem; padding: 0 1rem; color: #222; }
9	    form { display: grid; grid-template-columns: max-content 1fr; gap: .5rem 1rem; align-items: center; margin-bottom: 1rem; }
10	    form button { grid-column: 2; justify-self: start; }
11	    [data-testid="form-error"] { color: #b00020; min-height: 1.2em; margin-bottom: 1rem; }
12	    [data-testid="job-list"] { list-style: none; padding: 0; }
13	    [data-testid="job-item"] { border: 1px solid #ccc; border-radius: 4px; padding: .5rem .75rem; margin-bottom: .5rem; }
14	    [data-testid="job-status"] { font-weight: 600; margin-right: .75rem; }
15	    [data-testid="job-progress"] { font-variant-numeric: tabular-nums; margin-right: .75rem; }
16	    [data-testid="job-result"] { font-family: ui-monospace, monospace; word-break: break-all; }
17	  </style>
18	</head>
19	<body>
20	  <h1>Job tracker</h1>
21	
22	  <form data-testid="job-form" novalidate>
23	    <label for="job-input">Input</label>
24	    <input id="job-input" data-testid="job-input" type="text" maxlength="1000" required>
25	
26	    <label for="job-steps">Steps</label>
27	    <input id="job-steps" data-testid="job-steps" type="text" inputmode="numeric" placeholder="5">
28	
29	    <label for="job-fail-attempts">Fail attempts</label>
30	    <input id="job-fail-attempts" data-testid="job-fail-attempts" type="text" inputmode="numeric" placeholder="0">
31	
32	    <button type="submit" data-testid="job-submit">Submit job</button>
33	  </form>
34	
35	  <div data-testid="form-error" role="alert"></div>
36	
37	  <ul data-testid="job-list"></ul>
38	
39	  <script>
40	    const form = document.querySelector('[data-testid="job-form"]');
41	    const inputEl = document.querySelector('[data-testid="job-input"]');
42	    const stepsEl = document.querySelector('[data-testid="job-steps"]');
43	    const failEl = document.querySelector('[data-testid="job-fail-attempts"]');
44	    const submitBtn = document.querySelector('[data-testid="job-submit"]');
45	    const errorEl = document.querySelector('[data-testid="form-error"]');
46	    const listEl = document.querySelector('[data-testid="job-list"]');
47	
48	    const NUMERIC = /^[+-]?\d+(\.\d+)?$/;
49	
50	    // Numeric text becomes a number so the API validates it; anything else is sent as typed so the API rejects it.
51	    // Empty fields are omitted so the API defaults apply.
52	    function toValue(text) {
53	      const t = text.trim();
54	      if (t === '') return undefined;
55	      return NUMERIC.test(t) ? Number(t) : t;
56	    }
57	
58	    function describeRejection(body, fallback) {
59	      const err = body && body.error;
60	      if (!err) return fallback;
61	      const fields = Array.isArray(err.fields) && err.fields.length
62	        ? ' (' + err.fields.map((f) => f.field + ': ' + f.message).join('; ') + ')'
63	        : '';
64	      return (err.message || 'Request rejected.') + fields;
65	    }
66	
67	    form.addEventListener('submit', async (event) => {
68	      event.preventDefault();
69	      const body = { input: inputEl.value };
70	      const steps = toValue(stepsEl.value);
71	      const failAttempts = toValue(failEl.value);
72	      if (steps !== undefined) body.steps = steps;
73	      if (failAttempts !== undefined) body.failAttempts = failAttempts;
74	
75	      submitBtn.disabled = true;
76	      errorEl.textContent = '';
77	      try {
78	        const res = await fetch('/api/jobs', {
79	          method: 'POST',
80	          headers: { 'content-type': 'application/json' },
81	          body: JSON.stringify(body),
82	        });
83	        const json = await res.json().catch(() => undefined);
84	        if (res.status === 201 || res.status === 200) {
85	          inputEl.value = '';
86	          stepsEl.value = '';
87	          failEl.value = '';
88	          await refresh();
89	        } else {
90	          errorEl.textContent = 'Submission rejected: ' + describeRejection(json, 'HTTP ' + res.status);
91	        }
92	      } catch (err) {
93	        errorEl.textContent = 'Submission failed: could not reach the server.';
94	      } finally {
95	        submitBtn.disabled = false;
96	      }
97	    });
98	
99	    function renderJob(job) {
100	      const li = document.createElement('li');
101	      li.setAttribute('data-testid', 'job-item');
102	      li.setAttribute('data-job-id', job.id);
103	
104	      const status = document.createElement('span');
105	      status.setAttribute('data-testid', 'job-status');
106	      status.textContent = job.status;
107	
108	      const progress = document.createElement('span');
109	      progress.setAttribute('data-testid', 'job-progress');
110	      progress.textContent = job.progress.completed + '/' + job.progress.total;
111	
112	      const result = document.createElement('span');
113	      result.setAttribute('data-testid', 'job-result');
114	      if (job.status === 'completed' && job.result) result.textContent = job.result.output;
115	      else if (job.status === 'failed') result.textContent = job.error || '';
116	      else result.textContent = '';
117	
118	      li.append(status, progress, result);
119	      return li;
120	    }
121	
122	    async function refresh() {
123	      try {
124	        const res = await fetch('/api/jobs');
125	        if (!res.ok) return;
126	        const { jobs } = await res.json();
127	        listEl.replaceChildren(...jobs.map(renderJob));
128	      } catch (err) {
129	        // Keep the last rendered list; the next poll will try again.
130	      }
131	    }
132	
133	    refresh();
134	    setInterval(refresh, 1000);
135	  </script>
136	</body>
